(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const w2x = Math.sin((x+w1x)*0.012+t*0.15)*8 + Math.cos((y+w1y)*0.01-t*0.12)*6;
  const w2y = Math.cos((y+w1y)*0.014+t*0.17)*8 + Math.sin((x+w1x)*0.011+t*0.2)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.075, 2.1, 0.0],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 1.2],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.45+1)*95, 0.055, 2.5, 2.5],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.4, 3.8],
    [370+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8, 5.0],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.085, 2.0, 0.8],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.4+1)*50, 0.13, 1.6, 4.2],
    [420+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.65+4)*55, 0.095, 2.3, 2.0]
  ];
  let aS=0, iS=0, wS=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a = Math.sin(d*f-t*sp+ph);
    const b = Math.sin(d*f*0.7+t*sp*0.55+ph+1.5);
    const w = Math.sin(d*f*1.3-t*sp*0.8+ph+3.0)*0.6;
    aS += a; iS += b; wS += w;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, wav = wS/n;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2;
  const bg2 = (Math.sin((sx+sy)*0.1+t*2.2)+Math.sin((sx-sy)*0.085-t*1.8))*0.25;
  const bg3 = Math.sin(sx*0.06+Math.sin(sy*0.05+t)*2+t*1.5)*0.15;
  const bg = bg1+bg2+bg3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0)*0.7;
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.0)*0.3;
  const spiral = (sp1+sp2+sp3)*0.35;
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.07-sy*0.11+t*0.7)*0.3)*1.4)*0.25;
  const ripple = Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.005)*0.3;
  const raw = act - inh*0.65 + bg*0.25 + spiral + cell + wav*0.2 + ripple;
  const reaction = Math.tanh(raw*2.0);
  const blend = reaction*0.7 + cell*0.3;
  const v = blend*0.5+0.5;
  const edge = Math.abs(reaction);
  const glow = Math.max(0, edge-0.6)*2.5;
  const pal = [
    [6,12,52],[12,45,85],[18,95,115],[30,155,135],
    [120,190,100],[210,195,60],[235,145,55],
    [215,85,60],[160,45,70],[90,22,55],[40,14,48],[6,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const pulse = 0.85+Math.sin(reaction*Math.PI*1.5)*0.15;
  const edgeBoost = edge>0.65?1.0+glow*0.35:1.0;
  const bri = pulse*edgeBoost;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const gr = glow*0.4;
  return [
    Math.min(255, (r0*bri + gr*180)|0),
    Math.min(255, (g0*bri + gr*220)|0),
    Math.min(255, (b0*bri + gr*255)|0)
  ];
}
